// Generate Dolphin's free replacement DROM coefficients (not Nintendo ROM data).
// Adapted from docs/DSP/free_dsp_rom/generate_coefs.py at Dolphin revision
// a2efdf1197be8132674b90fe9cf4761df39752ed. See THIRD_PARTY.md.
// The generated bytes are checked against the pinned replacement's SHA-256.
export const DSP_COEFFICIENT_SHA256 = 'd7741279c2e8ec5c5fb318f8fbdd6de6bf583520d288e836a5383233a4238179';
function i0(x) {
  let sum=1,term=1;
  for(let k=1;k<100;k++) {term*=x*x/(4*k*k);sum+=term;if(term<sum*1e-16)break;}
  return sum;
}
function roundEven(x) {
  const lo=Math.floor(x),fraction=x-lo;
  return fraction===0.5 ? lo+(lo%2!==0?1:0) : Math.round(x);
}
export function replacementDspCoefficients() {
  const values=[], beta=Math.PI*9/4, denominator=i0(beta);
  for(const [cutoff,kaiser] of [[0.5,false],[0.75,true],[1,false]]) {
    const filter=Array.from({length:512},(_,i)=>{
      const x=(-2+i*(4/511))*cutoff;
      const sinc=x===0?1:Math.sin(Math.PI*x)/(Math.PI*x);
      const window=kaiser?i0(beta*Math.sqrt(Math.max(0,1-(2*i/511-1)**2)))/denominator:0.54-0.46*Math.cos(2*Math.PI*i/511);
      return sinc*window;
    });
    const phases=Array.from({length:128},(_,i)=>[filter[127-i],filter[255-i],filter[383-i],filter[511-i]]);
    const scale=32767/Math.max(...phases.map(row=>row.reduce((a,b)=>a+b,0)));
    for(const row of phases)for(const value of row)values.push(roundEven(value*scale)&65535);
  }
  values.push(...Array(512).fill(0));
  for(const [address,value] of [[0x03b,0x0065],[0x043,0x0076],[0x0ca,0x3461],[0x0e2,0x376f],[0x1b8,0x007f],[0x1f8,0x0009],[0x1fc,0x0003],[0x229,0x657c],[0x231,0x64fc],[0x259,0x6143],[0x285,0x5aff],[0x456,0x102f],[0x468,0xf808],[0x491,0x6a0f],[0x5f1,0x0200],[0x5f6,0x7f65],[0x65b,0],[0x66b,0],[0x66c,0x06f2],[0x6fe,0x0008],[0x723,0xffe0],[0x766,0x0273]])values[address]=value;
  const result=new Uint8Array(4096),view=new DataView(result.buffer);
  values.forEach((value,index)=>view.setUint16(index*2,value,false));
  return result;
}
